import (
	"context"
	"encoding/json"
	"errors"
	"net/http"
	"strconv"
	"time"
)

// Charges is what the handlers need, declared where it is used. Anything
// with these methods satisfies it, with no implements clause: the service in
// main, and a fake in the tests.
type Charges interface {
	Create(ctx context.Context, in NewCharge) (Charge, error)
	Get(ctx context.Context, id int64) (Charge, error)
	Latest(ctx context.Context) (Charge, error)
	Report(ctx context.Context, seconds int) error
}

type ReceiptSender interface {
	SendAsync(ctx context.Context, p Charge)
}

type Handlers struct {
	charges Charges
	receipts ReceiptSender
}

func NewHandlers(charges Charges, receipts ReceiptSender) *Handlers {
	if charges == nil || receipts == nil {
		panic("NewHandlers: a dependency is nil")
	}
	return &Handlers{charges: charges, receipts: receipts}
}

func (h *Handlers) create(w http.ResponseWriter, r *http.Request) {
	var in NewCharge
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	if err := dec.Decode(&in); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	if in.Amount <= 0 {
		http.Error(w, "amount must be positive", http.StatusBadRequest)
		return
	}
	p, err := h.charges.Create(r.Context(), in)
	if errors.Is(err, ErrOverLimit) {
		http.Error(w, err.Error(), http.StatusUnprocessableEntity)
		return
	}
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	// The receipt outlives the request, so it must not inherit the request's
	// cancellation. WithoutCancel keeps its values and drops its lifetime.
	h.receipts.SendAsync(context.WithoutCancel(r.Context()), p)
	writeJSON(w, http.StatusCreated, p)
}

func (h *Handlers) get(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.ParseInt(r.PathValue("id"), 10, 64)
	if err != nil {
		http.Error(w, "id must be a number", http.StatusBadRequest)
		return
	}
	h.respond(w, r, func(ctx context.Context) (Charge, error) {
		return h.charges.Get(ctx, id)
	})
}

func (h *Handlers) latest(w http.ResponseWriter, r *http.Request) {
	h.respond(w, r, h.charges.Latest)
}

func (h *Handlers) respond(w http.ResponseWriter, r *http.Request,
	load func(context.Context) (Charge, error)) {
	p, err := load(r.Context())
	if errors.Is(err, ErrNotFound) {
		http.Error(w, err.Error(), http.StatusNotFound)
		return
	}
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	writeJSON(w, http.StatusOK, p)
}

// slow passes the request's context to the database, so a client that gives
// up cancels the query too.
func (h *Handlers) slow(w http.ResponseWriter, r *http.Request) {
	seconds, _ := strconv.Atoi(r.URL.Query().Get("seconds"))
	start := time.Now()
	if err := h.charges.Report(r.Context(), seconds); err != nil {
		http.Error(w, err.Error(), http.StatusServiceUnavailable)
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{
		"slept": time.Since(start).Round(time.Second).String()})
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(v)
}
// Command charges serves the same API as spring-charges with the standard
// library's net/http and database/sql, and the pgx driver for Postgres.
// Everything a Spring container would wire is wired here, by hand, in main.
package main

import (
	"context"
	"database/sql"
	"errors"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	_ "github.com/jackc/pgx/v5/stdlib"
)

func main() {
	db, err := sql.Open("pgx", env("DATABASE_URL",
		"postgres://charges:charges@localhost:5442/charges"))
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(4)
	if err := migrate(db); err != nil {
		log.Fatal(err)
	}

	// Bottom up: each constructor asks for what it needs.
	store := NewStore(db)
	receipts := NewReceipts(db)
	charges := NewChargeService(store)
	handlers := NewHandlers(charges, receipts)

	mux := http.NewServeMux()
	mux.HandleFunc("GET /charges/{id}", handlers.get)
	mux.HandleFunc("GET /charges/latest", handlers.latest)
	mux.HandleFunc("POST /charges", handlers.create)
	mux.HandleFunc("GET /reports/slow", handlers.slow)

	srv := &http.Server{
		Addr:              ":" + env("PORT", "8093"),
		Handler:           logRequests(mux),
		ReadHeaderTimeout: 5 * time.Second,
		IdleTimeout:       60 * time.Second,
	}
	serve(srv, receipts)
}

// serve runs until SIGTERM or SIGINT, stops accepting new requests, lets the
// in-flight ones finish, then waits for receipts still being sent.
func serve(srv *http.Server, receipts *Receipts) {
	ctx, stop := signal.NotifyContext(context.Background(),
		os.Interrupt, syscall.SIGTERM)
	defer stop()
	go func() {
		err := srv.ListenAndServe()
		if err != nil && !errors.Is(err, http.ErrServerClosed) {
			log.Fatal(err)
		}
	}()
	log.Printf("listening on %s", srv.Addr)
	<-ctx.Done()
	log.Print("shutting down, waiting for in-flight requests")
	shutdown, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	if err := srv.Shutdown(shutdown); err != nil {
		log.Print(err)
	}
	// Server.Shutdown knows about HTTP connections, not about goroutines this
	// application started. Those are ours to wait for, inside the same bound.
	if err := receipts.Wait(shutdown); err != nil {
		log.Printf("receipts still in flight: %v", err)
	}
	log.Print("stopped")
}

// logRequests is middleware: a function that wraps a handler. Authentication,
// correlation IDs and metrics compose the same way.
func logRequests(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		next.ServeHTTP(w, r)
		log.Printf("%s %s %s", r.Method, r.URL.Path,
			time.Since(start).Round(time.Millisecond))
	})
}

func env(key, fallback string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return fallback
